            "text": "{\"findings\":[{\"tipo\":\"GC\",\"causa_raiz\":\"A concatenacao repetida de strings em laco (s += i.ToString()) e a criacao de novos arrays de objetos a cada frame dentro de Update() alocam aproximadamente 8 MB de memoria gerenciada por frame. Isso sobrecarrega o Garbage Collector da Unity, que interrompe o processamento da CPU por ate 24.57ms para limpar o lixo na memoria, causando engasgos (stutter).\",\"codigo_refatorado\":\"using System; using System.Text; using System.Collections.Generic; using UnityEngine; using UnityEngine.Pool; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; [Range(1, 512)] public int cpuScansPerFrame = 1; public int emptyObjects = 0; public int gcConcatIterations = 1000; public int gcArrayAllocs = 0; public int overdrawLayers = 0; public Material overdrawMaterial; [Range(0, 2000)] public int prepopulateCount = 0; private MaterialPropertyBlock propBlock; private static readonly int ColorProp = Shader.PropertyToID(\\\"_Color\\\"); private ObjectPool\u003cGameObject\u003e pool; private readonly List\u003cGameObject\u003e activeObjects = new List\u003cGameObject\u003e(); private readonly StringBuilder sb = new StringBuilder(4096); private GameObject[] cachedSceneObjects; private void Awake() { propBlock = new MaterialPropertyBlock(); if (testPrefab != null) { pool = new ObjectPool\u003cGameObject\u003e(() =\u003e Instantiate(testPrefab), go =\u003e go.SetActive(true), go =\u003e go.SetActive(false), go =\u003e Destroy(go), false, 100, 2000); } } private void Start() { if (prepopulateCount \u003e 0 && pool != null) { for (int i = 0; i \u003c prepopulateCount; i++) SpawnOne(); } for (int i = 0; i \u003c emptyObjects; i++) new GameObject(\\\"Empty_\\\" + i); if (overdrawLayers \u003e 0 && overdrawMaterial != null) BuildOverdrawLayers(); cachedSceneObjects = FindObjectsOfType\u003cGameObject\u003e(); } private void BuildOverdrawLayers() { Camera cam = Camera.main; if (cam == null) return; float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad; for (int i = 0; i \u003c overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; var quad = GameObject.CreatePrimitive(PrimitiveType.Quad); Destroy(quad.GetComponent\u003cCollider\u003e()); quad.name = \\\"Overdraw_\\\" + i; quad.transform.SetParent(cam.transform, false); quad.transform.localPosition = new Vector3(0f, 0f, d); quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f); quad.GetComponent\u003cRenderer\u003e().sharedMaterial = overdrawMaterial; } } private void Update() { if (stressGc) { sb.Clear(); for (int i = 0; i \u003c gcConcatIterations; i++) sb.Append(i); } if (stressCpu) { if (cachedSceneObjects == null) cachedSceneObjects = FindObjectsOfType\u003cGameObject\u003e(); } if (stressDraw && pool != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i \u003c n; i++) SpawnOne(); } } private void SpawnOne() { if (pool == null) return; var clone = pool.Get(); clone.transform.position = UnityEngine.Random.insideUnitSphere * spawnRadius; clone.transform.rotation = Quaternion.identity; activeObjects.Add(clone); if (useUniqueMaterials) { var rend = clone.GetComponent\u003cRenderer\u003e(); if (rend != null) { rend.GetPropertyBlock(propBlock); propBlock.SetColor(ColorProp, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value)); rend.SetPropertyBlock(propBlock); } } } } }\",\"explicacao_didatica\":\"Em C#, somar textos usando o operador '+' cria uma nova copia na memoria toda vez. Fazer isso centenas de vezes por frame cria toneladas de lixo. O Garbage Collector precisa parar o jogo inteiro para limpar a memoria descartada, gerando travamentos. Substituimos isso reutilizando um unico StringBuilder e eliminando arrays temporarios no Update.\"},{\"tipo\":\"CPU\",\"causa_raiz\":\"O metodo GameObject.FindObjectsOfType foi chamado dentro do laco de Update(), forcando a CPU a inspecionar todos os GameObjects da hierarquia diversas vezes por frame, gerando um tempo maximo de frame de 380.73ms (muito acima do orcamento de 16.7ms). Somado a isso, o uso repetido de Instantiate() e o acesso direto a renderer.material causam picos de processamento e clonagem indevida de materiais.\",\"codigo_refatorado\":\"using System; using System.Text; using System.Collections.Generic; using UnityEngine; using UnityEngine.Pool; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; [Range(1, 512)] public int cpuScansPerFrame = 1; public int emptyObjects = 0; public int gcConcatIterations = 1000; public int gcArrayAllocs = 0; public int overdrawLayers = 0; public Material overdrawMaterial; [Range(0, 2000)] public int prepopulateCount = 0; private MaterialPropertyBlock propBlock; private static readonly int ColorProp = Shader.PropertyToID(\\\"_Color\\\"); private ObjectPool\u003cGameObject\u003e pool; private readonly List\u003cGameObject\u003e activeObjects = new List\u003cGameObject\u003e(); private readonly StringBuilder sb = new StringBuilder(4096); private GameObject[] cachedSceneObjects; private void Awake() { propBlock = new MaterialPropertyBlock(); if (testPrefab != null) { pool = new ObjectPool\u003cGameObject\u003e(() =\u003e Instantiate(testPrefab), go =\u003e go.SetActive(true), go =\u003e go.SetActive(false), go =\u003e Destroy(go), false, 100, 2000); } } private void Start() { if (prepopulateCount \u003e 0 && pool != null) { for (int i = 0; i \u003c prepopulateCount; i++) SpawnOne(); } for (int i = 0; i \u003c emptyObjects; i++) new GameObject(\\\"Empty_\\\" + i); if (overdrawLayers \u003e 0 && overdrawMaterial != null) BuildOverdrawLayers(); cachedSceneObjects = FindObjectsOfType\u003cGameObject\u003e(); } private void BuildOverdrawLayers() { Camera cam = Camera.main; if (cam == null) return; float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad; for (int i = 0; i \u003c overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; var quad = GameObject.CreatePrimitive(PrimitiveType.Quad); Destroy(quad.GetComponent\u003cCollider\u003e()); quad.name = \\\"Overdraw_\\\" + i; quad.transform.SetParent(cam.transform, false); quad.transform.localPosition = new Vector3(0f, 0f, d); quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f); quad.GetComponent\u003cRenderer\u003e().sharedMaterial = overdrawMaterial; } } private void Update() { if (stressGc) { sb.Clear(); for (int i = 0; i \u003c gcConcatIterations; i++) sb.Append(i); } if (stressCpu) { if (cachedSceneObjects == null) cachedSceneObjects = FindObjectsOfType\u003cGameObject\u003e(); } if (stressDraw && pool != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i \u003c n; i++) SpawnOne(); } } private void SpawnOne() { if (pool == null) return; var clone = pool.Get(); clone.transform.position = UnityEngine.Random.insideUnitSphere * spawnRadius; clone.transform.rotation = Quaternion.identity; activeObjects.Add(clone); if (useUniqueMaterials) { var rend = clone.GetComponent\u003cRenderer\u003e(); if (rend != null) { rend.GetPropertyBlock(propBlock); propBlock.SetColor(ColorProp, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value)); rend.SetPropertyBlock(propBlock); } } } } }\",\"explicacao_didatica\":\"Buscar objetos na cena inteira atraves de FindObjectsOfType a cada frame e como reler um dicionario inteiro do inicio ao fim toda vez que voce quer checar uma unica palavra. Movemos essa busca para o Start() guardando a referencia em cache. Alem disso, em vez de criar e destruir objetos continuamente com Instantiate, passamos a reutiliza-los usando Object Pooling, e usamos MaterialPropertyBlock para mudar cores sem duplicar materiais na memoria.\"}],\"dicas_level_design\":null}",
